<script setup>
import SocialFooter from "../components/SocialFooter.vue";
import Icon from "../components/Icon.vue";
import {dramaWeekdays} from './i18n.js';
import {useDramaI18n} from './useDramaI18n.js';
const {language,tr}=useDramaI18n();
import {useAccountStore} from '../stores/account';import {useEventsStore} from '../stores/events';
const account=useAccountStore(),personalEvents=useEventsStore();
const favoriteBusy=ref(false);
async function favoriteDrama(){if(favoriteBusy.value||!selected.value)return;personalEvents.personalError='';if(!account.user){personalEvents.personalError=tr('请先登录后收藏剧集');return;}favoriteBusy.value=true;try{await personalEvents.toggleFavorite('drama:'+selected.value.drama.id);}finally{favoriteBusy.value=false;}}


import {dramaMatchesSearch,platformToday,clampLibraryPage,validateDramaSnapshot} from './calendarState.js';
import {toggleSentinelFilter} from '../utils/filterSelection.js';
import BaseModal from '../components/BaseModal.vue';
import {broadcastStatus,onAirStatistics,sortLibrary,visibleProduction,sortCalendarSlots,effectiveWeekdays} from './library.js';
import {dramaCategoryStyle} from './categoryColors.js';
import {calendarAction,visibleEventCount} from '../utils/calendarDisplay.js';
import {dramaTypes} from './schedule.js';
import CalendarMonthBar from '../components/CalendarMonthBar.vue';
import {dramaImages} from './images.js';
import DramaImageGallery from './DramaImageGallery.vue';
import CalendarSectionHeading from '../components/CalendarSectionHeading.vue';
import {resolvePlatformLogo,matchedPlatform} from './platforms.js';
const platformLogo=p=>resolvePlatformLogo(p,import.meta.env.BASE_URL);
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick,onActivated,onDeactivated} from 'vue';
import DramaSubmission from './DramaSubmission.vue';
import {call} from '../api/supabase';
import {createDramaIntake} from './intake.js';
import {initialData} from './seed.js';
import {generateSchedule,dramaTitle,announcementsForEpisode} from './schedule.js';
const correctionPicker=ref(false),correctionId=ref('');
function chooseCorrection(){const d=drama(correctionId.value);if(!d)return;open(d);correctionPicker.value=false;correctionOpen.value=true;correctionNotice.value='';}
const submissionOpen=ref(false),correctionOpen=ref(false),correctionText=ref(''),correctionNotice=ref('');
const correctionBusy=ref(false);let correctionRequest=crypto.randomUUID();
async function saveCorrection(){if(correctionBusy.value||!correctionText.value.trim())return;correctionBusy.value=true;try{await createDramaIntake(call)({id:correctionRequest,kind:'correction',seriesId:selected.value.drama.id,payload:{message:correctionText.value.trim()}});correctionNotice.value='已提交剧集纠错审核。';correctionText.value='';correctionRequest=crypto.randomUUID();}catch(e){correctionNotice.value=e.message;}finally{correctionBusy.value=false;}}
function weekDateLabel(day){return day.slice(5).replace('-','.')+' ('+dramaWeekdays(language.currentLanguage)[new Date(day+'T12:00:00Z').getUTCDay()]+')';}
const key='chob-drama-private-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
const props=defineProps({embedded:Boolean,publicMode:Boolean,focusDramaId:String,scheduleArtists:{type:Array,default:()=>[]},loadSnapshot:{type:Function,default:null}});
const db=ref(props.loadSnapshot?{dramas:[],changes:[],events:[],platforms:[],artists:[]}:saved?.dramas && saved?.platforms && saved?.events && saved?.changes && saved?.artists?saved:structuredClone(initialData));
const storageError=ref(''),loading=ref(true);
let polling,refreshRevision=0;
async function refresh(){const revision=++refreshRevision;try{let snapshot;if(props.loadSnapshot){snapshot=await props.loadSnapshot();}else{const response=await fetch('/__drama_test_data');if(!response.ok)throw Error('测试数据读取失败');snapshot=await response.json();}if(revision!==refreshRevision)return;db.value=validateDramaSnapshot(snapshot);storageError.value='';}catch(e){if(revision!==refreshRevision)return;storageError.value=tr(e.message);}finally{if(revision===refreshRevision)loading.value=false;}}
watch(()=>account.user?.id,()=>{if(props.loadSnapshot){++refreshRevision;selected.value=null;eventSelected.value=null;db.value={dramas:[],changes:[],events:[],platforms:[],artists:[]};loading.value=true;refresh();}});
function startPolling(){if(!polling)polling=setInterval(refresh,props.loadSnapshot?30000:2000);}
function stopPolling(){++refreshRevision;clearInterval(polling);polling=null;}
let hasActivated=false;onMounted(()=>{refresh();startPolling();});onActivated(()=>{if(hasActivated)refresh();hasActivated=true;startPolling();});onDeactivated(stopPolling);onBeforeUnmount(stopPolling);


defineExpose({prepareTutorial(step){tab.value=step==='library'?'library':'calendar';}});
const tab=ref('calendar'),month=ref(platformToday().slice(0,7)),search=ref(''),selected=ref(null),error=ref(''),notice=ref(''),eventSelected=ref(null),unused=ref(null);

const posterHeight=ref(320),castOverflow=ref(false);let posterObserver,castObserver;
watch(()=>selected.value,async()=>{posterObserver?.disconnect();castObserver?.disconnect();castOverflow.value=false;posterHeight.value=320;await nextTick();const image=document.querySelector('.drama-detail-modal .drama-main-image');if(image){posterObserver=new ResizeObserver(entries=>{const h=entries[0]?.contentRect.height;if(h>0)posterHeight.value=h;});posterObserver.observe(image);}const list=document.querySelector('.drama-detail-modal .folio-cast-list');if(list){castObserver=new ResizeObserver(()=>castOverflow.value=list.scrollHeight>list.clientHeight+1);castObserver.observe(list);}},{flush:'post'});onBeforeUnmount(()=>{posterObserver?.disconnect();castObserver?.disconnect();});
const emit=defineEmits(['schedule','focused','tutorial','about']);
watch(()=>db.value.dramas,()=>{if(!selected.value)return;const updated=db.value.dramas.find(d=>d.id===selected.value.drama.id);if(!updated){selected.value=null;correctionOpen.value=false;return;}selected.value={...selected.value,drama:updated};});
watch([()=>props.focusDramaId,()=>db.value.dramas],()=>{if(props.focusDramaId){const d=db.value.dramas.find(d=>d.id===props.focusDramaId);if(d){open(d);emit('focused');}}});
const selectedCalendarDate=ref(new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'}));
const agendaDate=computed(()=>selectedCalendarDate.value.startsWith(month.value)?selectedCalendarDate.value:slots.value.find(s=>s.date.startsWith(month.value))?.date||month.value+'-01');
const title=dramaTitle;
function safe(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
const companyFilter=ref([]),typeFilter=ref([]),calendarMode=ref('month'),weekAnchor=ref(''),dayDialog=ref(''),dayType=ref('all');
const typeLabel=t=>({'Boys Love':'BL','Girls Love':'GL'}[t]||tr(t));
const companies=computed(()=>[...new Set(db.value.dramas.map(d=>d.productionCompany).filter(Boolean))].sort());
const matchesFilters=d=>(!companyFilter.value.length||companyFilter.value.includes(d.productionCompany))&&(!typeFilter.value.length||d.types.some(t=>typeFilter.value.includes(t)));
const broadcastFilter=ref([]),productionFilter=ref([]);
const statusFilters=[{key:'broadcast',label:'播出状态',options:['播出中','待播','已完播','未定档']},{key:'production',label:'制作进度',options:['已公布','未开机','已开机','已杀青']}];
function statusSelection(key){return key==='broadcast'?broadcastFilter:productionFilter;}
function toggleStatus(key,value,options,event){const target=statusSelection(key);target.value=toggleSentinelFilter(target.value,value,options);event.target.checked=!target.value.length||target.value.includes(value);}
const libraryFiltered=computed(()=>filtered.value.filter(d=>(!broadcastFilter.value.length||broadcastFilter.value.includes(['播出中','待播','已完播'].includes(status(d))?status(d):'未定档'))&&(!productionFilter.value.length||productionFilter.value.includes(d.production))));
const libraryPage=ref(1);const libraryPages=computed(()=>Math.max(1,Math.ceil(sorted.value.length/30)));const libraryPageRows=computed(()=>sorted.value.slice((libraryPage.value-1)*30,libraryPage.value*30));watch([search,companyFilter,typeFilter,broadcastFilter,productionFilter],()=>libraryPage.value=1);
const sort=ref('date');const libraryStats=computed(()=>onAirStatistics(db.value.dramas,db.value.changes));const sorted=computed(()=>sortLibrary(libraryFiltered.value,sort.value,db.value.changes));
watch(sort,()=>libraryPage.value=1);
const filtered=computed(()=>db.value.dramas.filter(matchesFilters).filter(d=>dramaMatchesSearch(d,search.value)));
watch(libraryPages,()=>libraryPage.value=clampLibraryPage(libraryPage.value,sorted.value.length));
const slots=computed(()=>{const out=[];for(const d of filtered.value)for(const r of d.rules){let rows=generateSchedule(d,r);for(const c of db.value.changes.filter(c=>c.original.dramaId===d.id&&c.original.ruleId===r.id)){rows=rows.map(s=>s.id===c.original.id?c.original:s);rows.push(c.replacement);}if(matchesFilters(d)&&(!broadcastFilter.value.length||broadcastFilter.value.includes(['播出中','待播','已完播'].includes(status(d))?status(d):'未定档'))&&(!productionFilter.value.length||productionFilter.value.includes(d.production)))out.push(...rows);}return sortCalendarSlots(out,db.value.dramas);});
const days=computed(()=>{if(!month.value)return [];if(calendarMode.value==='week'){const start=new Date((weekAnchor.value||month.value+'-01')+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-start.getUTCDay());return Array.from({length:7},(_,i)=>new Date(+start+i*86400000).toISOString().slice(0,10));}const start=new Date(month.value+'-01T00:00:00Z');const count=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate();return [...Array(start.getUTCDay()).fill(null),...Array.from({length:count},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`)];});
const notices=computed(()=>selected.value?.slot?announcementsForEpisode(db.value.changes.map(c=>c.announcement),selected.value.drama.id,selected.value.slot.episode):db.value.changes.filter(c=>c.announcement.dramaId===selected.value?.drama.id).map(c=>c.announcement));
function drama(id){return db.value.dramas.find(d=>d.id===id);}
function platform(id){return db.value.platforms.find(p=>p.id===id)||{name:id};}
function status(d){return broadcastStatus(d,db.value.changes);}
function open(d,slot=null){if(d){personalEvents.personalError='';selected.value={drama:d,slot};}}
const chineseMonths=['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'];
const englishMonths=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function shiftMonth(n){if(calendarMode.value==='day'){const d=new Date(agendaDate.value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);selectedCalendarDate.value=d.toISOString().slice(0,10);month.value=selectedCalendarDate.value.slice(0,7);return;}if(calendarMode.value==='week'){const d=new Date((weekAnchor.value||month.value+'-01')+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n*7);weekAnchor.value=d.toISOString().slice(0,10);month.value=weekAnchor.value.slice(0,7);return;}const d=new Date(month.value+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);month.value=d.toISOString().slice(0,7);}
const stats=computed(()=>['Boys Love','Girls Love','BG','Bromance'].map(type=>({type,label:typeLabel(type),count:filtered.value.filter(d=>d.types.includes(type)).length})));
function ruleWeekdays(rule){const date=selected.value?.slot?.date||new Date().toLocaleDateString('en-CA',{timeZone:rule.timezone||'Asia/Bangkok'});return effectiveWeekdays(rule,date).map(day=>dramaWeekdays(language.currentLanguage)[day]).join('、');}
const dayRows=computed(()=>slots.value.filter(s=>s.date===dayDialog.value&&(dayType.value==='all'||drama(s.dramaId).types.includes(dayType.value))));
function showDay(day){dayDialog.value=day;dayType.value='all';selectedCalendarDate.value=day;}
function finalEpisode(slot){return !drama(slot.dramaId)?.rules.find(r=>r.id===slot.ruleId)?.totalEpisodesUnknown&&slot.episode===Number(drama(slot.dramaId)?.rules.find(r=>r.id===slot.ruleId)?.totalEpisodes);}
function episodeLabel(slot){return finalEpisode(slot)?tr('最终集')+' · EP.'+slot.episode:slot.episode===1?tr('首集')+' · EP.1':'EP.'+slot.episode;}
function compactEpisodeLabel(slot){return finalEpisode(slot)?'Final':'EP.'+slot.episode;}
function specialEpisode(slot){return slot.episode===1||slot.episode===Number(drama(slot.dramaId)?.rules.find(r=>r.id===slot.ruleId)?.totalEpisodes);}
function slotClick(slot){if(calendarMode.value==='week'){open(drama(slot.dramaId),slot);return;}if(calendarAction(slots.value.filter(s=>s.date===slot.date).length,compactViewport.value)==='day')showDay(slot.date);else open(drama(slot.dramaId),slot);}
const compactViewport=ref(false);let viewportMedia;function updateViewport(){compactViewport.value=viewportMedia.matches;}onMounted(()=>{viewportMedia=window.matchMedia('(max-width:700px)');updateViewport();viewportMedia.addEventListener('change',updateViewport);});onBeforeUnmount(()=>viewportMedia?.removeEventListener('change',updateViewport));
function limit(day){if(calendarMode.value==='week')return slots.value.filter(s=>s.date===day).length;return Math.min(3,slots.value.filter(s=>s.date===day).length);}
function exclusiveFilter(event){const current=event.currentTarget.closest('details'),wasOpen=current.open;document.querySelectorAll('.drama-filter-menu[open]').forEach(menu=>menu.open=false);current.open=!wasOpen;}
function toggleChoice(target,value,options,event){const current=target==='company'?companyFilter:typeFilter;current.value=toggleSentinelFilter(current.value,value,options);event.target.checked=!current.value.length||current.value.includes(value);}
function today(){const key=platformToday();month.value=key.slice(0,7);weekAnchor.value=key;selectedCalendarDate.value=key;}
</script>
<template>
<div class="shell"><header v-if="!embedded"><a class="brand" href="#">CHOB<span>CALENDAR</span></a><span class="private">私人测试 · 隔离数据</span></header>
<main><div class="c-drama-hero" data-tour="drama-heading"><CalendarSectionHeading word="Drama" :chinese="tr('追剧日历')" eyebrow="SO MANY STORIES, SO LITTLE TIME" :description="tr('剧那么多 慢慢追 好故事 正在发生')" /><nav><button v-for="(label,id) in {calendar:'播出月历',library:'剧集库'}" :class="{active:tab===id}" @click="tab=id">{{tr(label)}}</button></nav></div><p v-if="loadSnapshot&&!publicMode" class="muted">{{tr('管理员私有数据库预览 · 未公开发布')}} <button @click="refresh">{{tr('刷新资料')}}</button></p><p v-if="storageError" role="alert">{{storageError}}</p><p v-if="notice" role="status">{{notice}}</p>
<section v-if="tab==='calendar'" class="c-drama-card" data-tour="drama-calendar"><section v-if="!loading&&!storageError" class="drama-stats" aria-label="剧集类别统计"><div v-for="stat in stats" :key="stat.type" :style="dramaCategoryStyle([stat.type])"><strong>{{stat.count}}</strong><span>{{tr(stat.label)}}</span></div></section><CalendarMonthBar hide-today :unit="calendarMode" :month="month" :title="language.currentLanguage==='zh'?chineseMonths[Number(month.slice(5))-1]:new Intl.DateTimeFormat(language.locale,{month:'long'}).format(new Date(month+'-01T12:00:00Z'))" :english="englishMonths[Number(month.slice(5))-1]" @previous="shiftMonth(-1)" @next="shiftMonth(1)" @today="today"><div class="drama-view-switch"><button :class="{active:calendarMode==='day'}" @click="calendarMode='day'">{{tr('日')}}</button><button :class="{active:calendarMode==='month'}" @click="calendarMode='month'">{{tr('月')}}</button><button :class="{active:calendarMode==='week'}" @click="calendarMode='week';weekAnchor=agendaDate">{{tr('周')}}</button></div></CalendarMonthBar><div class="drama-filter-row"><input class="drama-calendar-search" v-model="search" :placeholder="tr('搜索剧名、类型')" :aria-label="tr('搜索剧集')"><div class="drama-mobile-view"><button :class="{active:calendarMode==='day'}" @click="calendarMode='day'">{{tr('日')}}</button><button :class="{active:calendarMode==='month'}" @click="calendarMode='month'">{{tr('月')}}</button><button :class="{active:calendarMode==='week'}" @click="calendarMode='week';weekAnchor=agendaDate">{{tr('周')}}</button></div><details v-for="kind in ['company','type']" :key="kind" class="drama-filter-menu"><summary @click.prevent="exclusiveFilter($event)">{{tr(kind==='company'?'出品公司':'剧集类别')}}<span class="filter-chevron" aria-hidden="true"></span></summary><div class="drama-filter-options"><div><button @click="kind==='company'?companyFilter=[]:typeFilter=[]">{{tr('全选')}}</button><button @click="kind==='company'?companyFilter=['__none__']:typeFilter=['__none__']">{{tr('全不选')}}</button></div><label v-for="option in kind==='company'?companies:dramaTypes" :key="option"><input type="checkbox" :checked="!(kind==='company'?companyFilter:typeFilter).length||(kind==='company'?companyFilter:typeFilter).includes(option)" @change="toggleChoice(kind,option,kind==='company'?companies:dramaTypes,$event)">{{kind==='type'?typeLabel(option):option}}</label><p v-if="kind==='company'&&!companies.length">{{tr('暂无出品公司')}}</p></div></details><details v-for="filter in statusFilters" :key="filter.key" class="drama-filter-menu"><summary @click.prevent="exclusiveFilter($event)">{{tr(filter.label)}}<span v-if="statusSelection(filter.key).value.length" class="filter-count">{{statusSelection(filter.key).value.includes('__none__')?'0':statusSelection(filter.key).value.length}}</span><span class="filter-chevron" aria-hidden="true"></span></summary><div class="drama-filter-options"><div><button @click="statusSelection(filter.key).value=[]">{{tr('全选')}}</button><button @click="statusSelection(filter.key).value=['__none__']">{{tr('全不选')}}</button></div><label v-for="option in filter.options" :key="option"><input type="checkbox" :checked="!statusSelection(filter.key).value.length||statusSelection(filter.key).value.includes(option)" @change="toggleStatus(filter.key,option,filter.options,$event)">{{tr(option)}}</label></div></details></div><section v-if="calendarMode==='day'" class="drama-day-view"><header><h2>{{agendaDate}}</h2><span>{{tr('当天更新 · {n} 集',{n:slots.filter(s=>s.date===agendaDate&&s.status!=='changed').length})}}</span></header><button v-for="slot in slots.filter(s=>s.date===agendaDate)" :key="slot.id" class="drama-day-capsule" :class="{'episode-special':specialEpisode(slot)}" :style="dramaCategoryStyle(drama(slot.dramaId).types)" @click="open(drama(slot.dramaId),slot)"><span :class="{strike:slot.status==='changed'}">{{title(drama(slot.dramaId))}}</span><span class="drama-chip-type">{{episodeLabel(slot)}}</span></button><p v-if="!slots.some(s=>s.date===agendaDate)" class="muted">{{tr('当天暂无剧集更新')}}</p></section><div v-else class="calendar" :class="{'week-calendar':calendarMode==='week'}"><b v-for="(w,i) in dramaWeekdays(language.currentLanguage)" class="weekday" :class="{sunday:i===0,saturday:i===6}">{{w}}</b><div v-for="(day,index) in days" :key="day||index" class="day" :class="{blank:!day,sunday:day&&new Date(day+'T00:00:00Z').getUTCDay()===0,saturday:day&&new Date(day+'T00:00:00Z').getUTCDay()===6,'past-day':day&&day<new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'})}" @click.self="day&&showDay(day)"><button v-if="day" class="day-number" :aria-label="day" :aria-pressed="agendaDate===day" @click="showDay(day)">{{calendarMode==='week'?weekDateLabel(day):Number(day.slice(-2))}}</button><template v-if="day"><button v-for="s in slots.filter(s=>s.date===day).slice(0,limit(day))" :key="s.id" class="chip" :title="title(drama(s.dramaId))+(specialEpisode(s)?(s.episode===1?' · 首集':' · 最终集'):'')" :style="dramaCategoryStyle(drama(s.dramaId).types)" :class="{changed:s.status==='changed','episode-special':specialEpisode(s)}" @click="slotClick(s)"><span :class="{strike:s.status==='changed'}">{{title(drama(s.dramaId))}}</span><span v-if="s.status==='changed'"> · 剧集变动</span><span class="drama-chip-type"><span class="episode-label-full">{{episodeLabel(s)}}</span><span class="episode-label-compact">{{compactEpisodeLabel(s)}}</span></span></button><button v-if="slots.filter(s=>s.date===day).length>limit(day)" class="drama-more" @click="showDay(day)">{{tr('还有 {n} 项',{n:slots.filter(s=>s.date===day).length-limit(day)})}}</button></template></div></div></section>
<section v-if="tab==='library'" class="drama-library" data-tour="drama-library"><h2 class="library-heading">{{tr('正在播出')}}</h2><p v-if="storageError" role="alert">{{tr('统计暂时无法更新，请刷新重试。')}}</p><p v-else-if="loading" role="status">{{tr('正在读取剧集资料…')}}</p><div v-else class="library-stats"><article v-for="stat in libraryStats" :key="stat.type"><strong>{{stat.count}}</strong><span>{{tr(stat.label)}}</span></article></div><div class="drama-filter-row"><div class="drama-mobile-view"><button :class="{active:calendarMode==='day'}" @click="calendarMode='day'">{{tr('日')}}</button><button :class="{active:calendarMode==='month'}" @click="calendarMode='month'">{{tr('月')}}</button><button :class="{active:calendarMode==='week'}" @click="calendarMode='week';weekAnchor=agendaDate">{{tr('周')}}</button></div><details v-for="kind in ['company','type']" :key="kind" class="drama-filter-menu"><summary @click.prevent="exclusiveFilter($event)">{{tr(kind==='company'?'出品公司':'剧集类别')}}<span class="filter-chevron" aria-hidden="true"></span></summary><div class="drama-filter-options"><div><button @click="kind==='company'?companyFilter=[]:typeFilter=[]">{{tr('全选')}}</button><button @click="kind==='company'?companyFilter=['__none__']:typeFilter=['__none__']">{{tr('全不选')}}</button></div><label v-for="option in kind==='company'?companies:dramaTypes" :key="option"><input type="checkbox" :checked="!(kind==='company'?companyFilter:typeFilter).length||(kind==='company'?companyFilter:typeFilter).includes(option)" @change="toggleChoice(kind,option,kind==='company'?companies:dramaTypes,$event)">{{kind==='type'?typeLabel(option):option}}</label><p v-if="kind==='company'&&!companies.length">{{tr('暂无出品公司')}}</p></div></details><details v-for="filter in statusFilters" :key="filter.key" class="drama-filter-menu"><summary @click.prevent="exclusiveFilter($event)">{{tr(filter.label)}}<span v-if="statusSelection(filter.key).value.length" class="filter-count">{{statusSelection(filter.key).value.includes('__none__')?'0'